CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Housemate');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','Housemate')); RETURN NEW; END $$;
CREATE TRIGGER pantry_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.households(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'Our home', invite_code text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(16),'hex'));
GRANT SELECT ON public.households TO authenticated; GRANT ALL ON public.households TO service_role; ALTER TABLE public.households ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.household_members(user_id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES public.households(id), display_name text NOT NULL);
GRANT SELECT ON public.household_members TO authenticated; GRANT ALL ON public.household_members TO service_role; ALTER TABLE public.household_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_household() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT household_id FROM public.household_members WHERE user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_household() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_household() TO authenticated;
CREATE POLICY household_read ON public.households FOR SELECT TO authenticated USING(id=public.my_household());
CREATE POLICY member_read ON public.household_members FOR SELECT TO authenticated USING(household_id=public.my_household());
CREATE TABLE public.pantry_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id), name text NOT NULL, category text NOT NULL DEFAULT 'Pantry', emoji text NOT NULL DEFAULT '🛒', shelf_life integer NOT NULL DEFAULT 7 CHECK(shelf_life BETWEEN 1 AND 3650), bought_on date, on_list boolean NOT NULL DEFAULT true, favorite boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pantry_items TO authenticated; GRANT ALL ON public.pantry_items TO service_role; ALTER TABLE public.pantry_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY item_access ON public.pantry_items FOR ALL TO authenticated USING(household_id=public.my_household()) WITH CHECK(household_id=public.my_household());
CREATE TABLE public.purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id), item_id uuid REFERENCES public.pantry_items(id) ON DELETE SET NULL, item_name text NOT NULL, emoji text NOT NULL, buyer_id uuid NOT NULL, buyer_name text NOT NULL, bought_on date NOT NULL);
GRANT SELECT ON public.purchases TO authenticated; GRANT ALL ON public.purchases TO service_role; ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY purchases_read ON public.purchases FOR SELECT TO authenticated USING(household_id=public.my_household());
CREATE FUNCTION public.setup_household(_name text, _code text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h uuid; n text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF public.my_household() IS NOT NULL THEN RAISE EXCEPTION 'Already in a household'; END IF; n:=trim(_name); IF length(n)<1 OR length(n)>60 THEN RAISE EXCEPTION 'Enter a name (1–60 characters)'; END IF; IF _code IS NOT NULL THEN SELECT id INTO h FROM public.households WHERE invite_code=trim(_code) FOR UPDATE; IF h IS NULL THEN RAISE EXCEPTION 'Invalid invite code'; END IF; IF (SELECT count(*) FROM public.household_members WHERE household_id=h)>=2 THEN RAISE EXCEPTION 'This household already has two members'; END IF; ELSE INSERT INTO public.households DEFAULT VALUES RETURNING id INTO h; END IF; INSERT INTO public.household_members VALUES(auth.uid(),h,n); UPDATE public.profiles SET display_name=n WHERE id=auth.uid(); IF _code IS NULL THEN INSERT INTO public.pantry_items(household_id,name,category,emoji,shelf_life) VALUES(h,'Eggs','Dairy & Eggs','🥚',21),(h,'Milk','Dairy & Eggs','🥛',7),(h,'Bread','Bakery','🍞',5),(h,'Bananas','Produce','🍌',5),(h,'Tomatoes','Produce','🍅',7),(h,'Onions','Produce','🧅',30),(h,'Chicken','Meat & Protein','🍗',3),(h,'Rice','Pantry','🍚',60),(h,'Coffee','Drinks','☕',60),(h,'Cheese','Dairy & Eggs','🧀',14),(h,'Toilet paper','Household & Cleaning','🧻',30),(h,'Dish soap','Household & Cleaning','🧴',45),(h,'Cat food','Pet supplies','🐱',30); END IF; RETURN h; END $$;
REVOKE ALL ON FUNCTION public.setup_household(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.setup_household(text,text) TO authenticated;
CREATE FUNCTION public.buy_item(_id uuid, _today date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.pantry_items; n text; BEGIN SELECT * INTO i FROM public.pantry_items WHERE id=_id AND household_id=public.my_household() FOR UPDATE; IF i.id IS NULL THEN RAISE EXCEPTION 'Item not found'; END IF; IF _today < current_date-1 OR _today > current_date+1 THEN RAISE EXCEPTION 'Purchase must be today'; END IF; SELECT display_name INTO n FROM public.household_members WHERE user_id=auth.uid(); UPDATE public.pantry_items SET bought_on=_today,on_list=false WHERE id=_id; INSERT INTO public.purchases(household_id,item_id,item_name,emoji,buyer_id,buyer_name,bought_on) VALUES(i.household_id,i.id,i.name,i.emoji,auth.uid(),n,_today); END $$;
REVOKE ALL ON FUNCTION public.buy_item(uuid,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.buy_item(uuid,date) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.pantry_items, public.purchases, public.household_members;